## Implementation: High-Throughput Stream Gateway

Below is a production-grade TypeScript implementation of the WebSocket Stream Gateway using `ioredis` and native `ws` with connection heartbeat telemetry.

```typescript title="src/gateway/streamGateway.ts"
import { WebSocketServer, WebSocket } from "ws"
import Redis from "ioredis"

interface ClientSession {
  userId: string
  ws: WebSocket
  isAlive: boolean
}

export class StreamGateway {
  private wss: WebSocketServer
  private redisPublisher: Redis
  private redisSubscriber: Redis
  private sessions = new Map<string, ClientSession>()

  constructor(port: number, redisUrl: string) {
    this.wss = new WebSocketServer({ port })
    this.redisPublisher = new Redis(redisUrl)
    this.redisSubscriber = new Redis(redisUrl)
    this.init()
  }

  private init(): void {
    this.wss.on("connection", (ws: WebSocket, req) => {
      const sessionId = crypto.randomUUID()
      const session: ClientSession = { userId: "anon", ws, isAlive: true }
      this.sessions.set(sessionId, session)

      ws.on("pong", () => {
        session.isAlive = true
      })

      ws.on("message", async (raw: string) => {
        try {
          const payload = JSON.parse(raw)
          // Append message to Redis Stream with automatic ID generation
          await this.redisPublisher.xadd(
            "stream:events",
            "*",
            "sessionId", sessionId,
            "type", payload.type,
            "data", JSON.stringify(payload.data)
          )
        } catch (err) {
          console.error("Stream ingestion error:", err)
        }
      })

      ws.on("close", () => {
        this.sessions.delete(sessionId)
      })
    })

    // Periodic Heartbeat to clean zombie connections
    setInterval(() => {
      this.sessions.forEach((session, id) => {
        if (!session.isAlive) {
          session.ws.terminate()
          this.sessions.delete(id)
          return
        }
        session.isAlive = false
        session.ws.ping()
      })
    }, 30000)
  }
}
```

> [!TIP]
> Always execute `ws.ping()` on a fixed 30-second interval to catch ungraceful client disconnections (such as mobile devices entering tunnels or sudden Wi-Fi loss) that leave half-open TCP sockets hanging.

