## Idempotent Payment Event Processing & Deduplication

Network retransmissions can cause Stripe to send identical webhook events multiple times. Processing an event twice could result in double-crediting user account seats or duplicate invoice generation. Persisting processed event IDs (`event.id`) inside an idempotent database table ensures strict single-execution semantics.

```typescript
import { prisma } from "@workspace/db";
import Stripe from "stripe";

export async function handleStripeEvent(event: Stripe.Event) {
  // Check if event has already been processed
  const existing = await prisma.webhookEvent.findUnique({
    where: { id: event.id }
  });

  if (existing) {
    console.log(`[Stripe] Skipping already processed event: ${event.id}`);
    return;
  }

  // Execute processing within isolated database transaction
  await prisma.$transaction(async (tx) => {
    switch (event.type) {
      case "customer.subscription.updated":
      case "customer.subscription.created": {
        const sub = event.data.object as Stripe.Subscription;
        await syncTenantSubscription(tx, sub);
        break;
      }
      case "invoice.payment_failed": {
        const invoice = event.data.object as Stripe.Invoice;
        await handlePaymentFailure(tx, invoice);
        break;
      }
    }

    // Record processed event
    await tx.webhookEvent.create({
      data: { id: event.id, type: event.type, processedAt: new Date() }
    });
  });
}
```

