## Multi-Tenant WebSocket Architecture & Room Allocation

To notify active browser tabs immediately when subscription statuses change, WebSocket connections are grouped into secure rooms segmented by tenant ID. When a webhook successfully processes a payment, an internal pub/sub event triggers a broadcast to the tenant's WebSocket channel.

```typescript
import { Server, Socket } from "socket.io";
import http from "http";

export function initWebSocketServer(server: http.Server) {
  const io = new Server(server, {
    cors: { origin: process.env.CLIENT_ORIGIN, credentials: true }
  });

  // Authenticate & join tenant room
  io.use((socket, next) => {
    const tenantId = socket.handshake.auth.tenantId;
    if (!tenantId) return next(new Error("Unauthorized tenant channel"));
    socket.data.tenantId = tenantId;
    next();
  });

  io.on("connection", (socket: Socket) => {
    const tenantId = socket.data.tenantId;
    socket.join(`tenant:${tenantId}`);
    console.log(`[WebSocket] Socket ${socket.id} joined room: tenant:${tenantId}`);
  });

  return io;
}
```

