## Fine-Grained Role-Based Access Control (RBAC) Middleware

Declarative RBAC middleware verifies user permissions prior to routing requests to controller logic, preventing unauthorized privilege escalation.

```typescript
import { Request, Response, NextFunction } from "express";

export function authorizeRoles(...allowedRoles: string[]) {
  return (req: Request, res: Response, next: NextFunction) => {
    const userRole = req.user?.role; // Set by auth middleware

    if (!userRole || !allowedRoles.includes(userRole)) {
      return res.status(403).json({
        error: "Forbidden: Insufficient security privileges"
      });
    }

    next();
  };
}
```

