## Producer Configuration & Durable Message Queuing

To prevent message loss during broker restarts or network partitions, message queues must be declared as durable, and messages marked persistent. Below is an example of an AMQP publisher module configured with connection retry logic and channel management.

```typescript
import amqp from "amqplib";

let connection: amqp.Connection | null = null;
let channel: amqp.Channel | null = null;

export async function getChannel(): Promise<amqp.Channel> {
  if (channel) return channel;

  connection = await amqp.connect(process.env.RABBITMQ_URL || "amqp://localhost:5672");
  channel = await connection.createChannel();

  // Assert dead letter exchange and poison-pill queue
  await channel.assertExchange("dlx_exchange", "direct", { durable: true });
  await channel.assertQueue("dlx_failed_jobs", { durable: true });
  await channel.bindQueue("dlx_failed_jobs", "dlx_exchange", "dlx_failed_jobs");

  return channel;
}

export async function publishTask(queueName: string, payload: object): Promise<boolean> {
  const ch = await getChannel();

  await ch.assertQueue(queueName, {
    durable: true,
    deadLetterExchange: "dlx_exchange",
    deadLetterRoutingKey: "dlx_failed_jobs"
  });

  return ch.sendToQueue(
    queueName,
    Buffer.from(JSON.stringify(payload)),
    { persistent: true, contentType: "application/json" }
  );
}
```

